for name in ['tet61-residue-scoped-acknowledgement','tet47-ground-what-is-owed','tet56-bounded-grep-return']:
    fp='/Volumes/SSD/Documents/lonic/tetel/docs/design/%s.md.tetel/facts.jsonl'%name
    buckets={}
