D='/Volumes/SSD/Documents/lonic/tetel/docs/design/'
ROOT='/Volumes/SSD/Documents/lonic/tetel'
RX=re.compile('/(?:Users|Volumes)/')
NOGIT='no-git-worktree'
for m in ['tet61-residue-scoped-acknowledgement.md','tet47-ground-what-is-owed.md','tet56-bounded-grep-return.md']:
    notes=0; lab=0; searchocc=0; searchnotunder=0
    for line in open(D+m+'.tetel/facts.jsonl'):
        line=line.strip()
        if not line: continue
        ev=json.loads(line)
        if ev.get('event')=='Create':
            notes+=len(RX.findall(ev['note']))
            for e in ev['extent']:
                lab+=len(RX.findall(e['label']))
                wr=e.get('world_root','')
                if e['key']==wr and wr not in ('',NOGIT):
                    for mm in RX.finditer(e['label']):
                        searchocc+=1
                        if not e['label'].startswith(ROOT,mm.start()): searchnotunder+=1
        elif ev.get('event')=='Revise':
            notes+=len(RX.findall(ev['note']))
    print(m,'note_occ(all events)',notes,'label_occ',lab,'search_occ',searchocc,'search_occ_not_under_ROOT',searchnotunder) (exit 0)

