RX=re.compile('/(?:Users|Volumes)/')
files=sorted(glob.glob('/Volumes/SSD/Documents/lonic/tetel/docs/design/*.md.evidence.jsonl'))
files=[f for f in files if 'tet42-committed' not in f]
print(len(files),'ledgers')
cnt=collections.Counter(); total=0
def walk(o,path):
    global total
    if isinstance(o,str):
        n=len(RX.findall(o))
        if n: cnt[path]+=n
    elif isinstance(o,dict):
        for k,v in o.items(): walk(v,path+'.'+k)
    elif isinstance(o,list):
        for v in o: walk(v,path+'[]')
for f in files:
    for line in open(f):
        line=line.strip()
        if not line: continue
        walk(json.loads(line),'')
for k,v in sorted(cnt.items()): print(v,k)
print('sum',sum(cnt.values())) (exit 0)

